#include <stdio.h>
#include <stdint.h>
#include <math.h>

int64_t prevPow2(int64_t n) {
    int64_t val = n;
    int64_t other = 1;
    while (other <= val) {
        if (other == val) {
            return other;
        }
        other = other * 2;
    }
    return other / 2;
}

int main() {
    int64_t tests[] = {1, 2, 3, 7, 8, 9, 15, 16, 17, 100, 1023, 1024, 1025, 65535, 65536, 65537, 2147483647, 2147483648, 9223372036854775807};
    int num_tests = sizeof(tests) / sizeof(tests[0]);
    for (int i = 0; i < num_tests; i++) {
        printf("%ld\n", prevPow2(tests[i]));
    }
    return 0;
}

