import java.util.*;

public class Solution {
    public static long prevPow2(long n) {
        long val = n;
        long other = 1;
        while (other <= val) {
            if (other == val) {
                return other;
            }
            other = other * 2;
        }
        return other / 2;
    }

    public static void main(String[] args) {
        System.out.println(prevPow2(1));
        System.out.println(prevPow2(2));
        System.out.println(prevPow2(5));
        System.out.println(prevPow2(16));
        System.out.println(prevPow2(100));
    }
}
